begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
select is((select count(*) from public.rbac_companies where name = 'Perforadora Integral de Oriente Ixachi' and is_active), 1::bigint, 'Ixachi company is active');
select is((select count(*) from public.rbac_company_modules cm join public.rbac_companies c on c.id = cm.company_id where c.name = 'Perforadora Integral de Oriente Ixachi' and cm.enabled and cm.module_key in ('hour-meters', 'trazabilidad', 'access-control')), 3::bigint, 'required modules are enabled');
select is((select count(*) from public.rbac_roles r join public.rbac_companies c on c.id = r.company_id where c.name = 'Perforadora Integral de Oriente Ixachi' and r.name in ('Supervisor Electrician', 'Supervisor Mechanic', 'Tool Pusher')), 3::bigint, 'company roles exist');
select is((select count(*) from public.rbac_memberships m join public.rbac_companies c on c.id = m.company_id where c.name = 'Perforadora Integral de Oriente Ixachi'), 5::bigint, 'Ixachi memberships are provisioned');
select is((select count(*) from public.rbac_assignments a join public.rbac_companies c on c.id = a.company_id where c.name = 'Perforadora Integral de Oriente Ixachi'), 5::bigint, 'Ixachi assignments are provisioned');
select is((select count(*) from public.locations where company_id = 'f1000000-0000-0000-0000-000000000001' and name in ('Rig 702', 'Rig 703') and type::text = 'rig' and is_active), 2::bigint, 'active production rigs exist');
select is((select count(*) from public.models where company_id = 'f1000000-0000-0000-0000-000000000001' and name in ('HH-2400', 'AA27647035', '3512C', 'GDM-850 AC', '35770000-H', 'PC3000-42-A-A-A-N-S', 'ST-100', '2B604808B15T32A-P')), 8::bigint, 'all requested models exist');
select is((select count(*) from public.brands where company_id = 'f1000000-0000-0000-0000-000000000001' and name in ('SICHUAN HONGUA PETROLEUM EQUIPMENT CO, LTD.', 'KATO ENGINEERING', 'CATERPILLAR', 'GLOBAL DRILLING SUPPORT', 'AMERICAN BLOCK', 'CANRIG', 'NATIONAL OILWELL VARCO')), 7::bigint, 'all requested brands exist');
select is((select count(*) from public.rbac_role_permissions rp join public.rbac_roles r on r.id = rp.role_id join public.rbac_permissions p on p.id = rp.permission_id where r.name in ('Supervisor Electrician', 'Supervisor Mechanic') and p.resource = 'hour-meters' and p.action in ('read', 'register', 'update')), 6::bigint, 'supervisors receive hourmeter capabilities');
select is((select count(*) from public.rbac_role_permissions rp join public.rbac_roles r on r.id = rp.role_id join public.rbac_permissions p on p.id = rp.permission_id where r.name = 'Tool Pusher' and p.resource = 'hour-meters' and p.action in ('read', 'register', 'update', 'manage')), 4::bigint, 'Tool Pusher receives hourmeter capabilities');
select is((select count(*) from public.rbac_role_permissions rp join public.rbac_roles r on r.id = rp.role_id join public.rbac_permissions p on p.id = rp.permission_id where r.name = 'Tool Pusher' and p.resource in ('assets', 'certificates') and p.action in ('read', 'create', 'update', 'delete')), 8::bigint, 'Tool Pusher receives CRUD');
select is((select count(*) from public.rbac_role_permissions rp join public.rbac_roles r on r.id = rp.role_id join public.rbac_permissions p on p.id = rp.permission_id where r.name in ('Supervisor Electrician', 'Supervisor Mechanic', 'Tool Pusher') and p.resource = 'trazabilidad' and p.action = 'read'), 3::bigint, 'roles receive traceability read');
select is((select count(*) from public.rbac_memberships where company_id = 'f1000000-0000-0000-0000-000000000001'), 5::bigint, 'Ixachi has five users');
select * from finish(); rollback;
